import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FoldedMapProps = Record<string, any>;

const FoldedMap: React.FC<FoldedMapProps> = ({
  backgroundColor = "#F4F4F5",
  transparentBackground = false,
  durationInSeconds = 3,
  mapSurfaceColor = "#FFFFFF",
  mapLineColor = "#18181B",
  accentColor = "#E63946",
  strokeWidth = 4,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Layout Dimensions
  const s = Math.min(width, height);
  const pW = s * 0.26;
  const pH = pW * 1.4;

  // Timings
  const totalFrames = Math.round(durationInSeconds * fps);
  const safeExitStart = Math.max(40, totalFrames - 35);

  // Entrance Springs (Quick, snappy unfold)
  const flyIn = spring({ fps, frame, config: { damping: 14, mass: 0.9, stiffness: 120 } });
  const leftUnfold = spring({ fps, frame: frame - 6, config: { damping: 12, mass: 0.8, stiffness: 140 } });
  const rightUnfold = spring({ fps, frame: frame - 12, config: { damping: 12, mass: 0.8, stiffness: 140 } });
  const pinDrop = spring({ fps, frame: frame - 22, config: { damping: 10, mass: 0.7, stiffness: 150 } });

  // Exit Springs (Crisp fold up and out)
  const pinExit = spring({ fps, frame: frame - safeExitStart, config: { damping: 14, mass: 0.8, stiffness: 140 } });
  const rightFold = spring({ fps, frame: frame - (safeExitStart + 5), config: { damping: 13, mass: 0.8, stiffness: 140 } });
  const leftFold = spring({ fps, frame: frame - (safeExitStart + 12), config: { damping: 13, mass: 0.8, stiffness: 140 } });
  const flyOut = spring({ fps, frame: frame - (safeExitStart + 18), config: { damping: 15, mass: 1, stiffness: 120 } });

  // Combined Progresses (0 to 1 to 0)
  const flyProgress = flyIn - flyOut;
  const leftProgress = leftUnfold - leftFold;
  const rightProgress = rightUnfold - rightFold;
  const pinProgress = pinDrop - pinExit;

  // Transforms
  const containerY = interpolate(flyProgress, [0, 1], [height * 0.8, 0]);
  const containerScale = interpolate(flyProgress, [0, 1], [0.3, 1]);
  const containerRotate = interpolate(flyProgress, [0, 1], [-5, 0]);
  const dropShadowY = interpolate(flyProgress, [0, 1], [0, 30]);
  const dropShadowBlur = interpolate(flyProgress, [0, 1], [0, 40]);

  // Panel Rotations
  const leftRotateY = interpolate(leftProgress, [0, 1], [179, 0]);
  const rightRotateY = interpolate(rightProgress, [0, 1], [-179, 0]);

  // Z-Index Adjustments to prevent clipping when completely folded
  const leftZ = interpolate(leftProgress, [0, 1], [2, 0]);
  const rightZ = interpolate(rightProgress, [0, 1], [1, 0]);

  // Internal Shadows simulating lighting on creases
  const extrapolateConfig = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
  const leftShadow = interpolate(leftProgress, [0, 1], [0.6, 0], extrapolateConfig);
  const rightShadow = interpolate(rightProgress, [0, 1], [0.6, 0], extrapolateConfig);
  const centerShadow = interpolate(leftProgress + rightProgress, [0, 2], [0.4, 0], extrapolateConfig);

  // Pin details
  const pinScale = Math.max(0, interpolate(pinProgress, [0, 1], [0, 1], extrapolateConfig));
  const pinY = interpolate(pinProgress, [0, 1], [-40, 0], extrapolateConfig);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Shared internal map graphic function
  const renderMapContent = (offsetX: number) => (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: offsetX,
        width: pW * 3,
        height: pH,
        backgroundColor: mapSurfaceColor,
        boxSizing: "border-box",
        transition: "none",
      }}
    >
      <svg width="100%" height="100%" viewBox="0 0 600 300" preserveAspectRatio="none" style={{ transition: "none" }}>
        {/* Abstract Topographic & Grid Lines */}
        <path d="M 200 0 L 200 300 M 400 0 L 400 300" stroke={mapLineColor} strokeWidth={strokeWidth / 2} opacity={0.15} strokeDasharray="6,6" />
        <path d="M 0 100 L 600 100 M 0 200 L 600 200" stroke={mapLineColor} strokeWidth={strokeWidth / 2} opacity={0.15} strokeDasharray="6,6" />
        
        {/* Rivers/Features */}
        <path d="M 120 0 C 180 80 50 180 150 300" stroke="#A8DADC" strokeWidth={strokeWidth * 5} fill="none" opacity={0.6} />
        <path d="M 460 0 C 400 100 500 220 440 300" stroke="#A8DADC" strokeWidth={strokeWidth * 5} fill="none" opacity={0.6} />

        {/* Main Route Line */}
        <path
          d="M 60 180 L 160 180 Q 250 180 300 140 T 480 140"
          stroke={mapLineColor}
          strokeWidth={strokeWidth * 2.5}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M 60 180 L 160 180 Q 250 180 300 140 T 480 140"
          stroke={mapSurfaceColor}
          strokeWidth={strokeWidth * 1}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {/* Origin Marker */}
        <circle cx="60" cy="180" r="10" fill={mapLineColor} />
        <circle cx="60" cy="180" r="4" fill={mapSurfaceColor} />
        <text x="60" y="155" fontFamily="Inter" fontWeight="800" fontSize="18" fill={mapLineColor} textAnchor="middle" letterSpacing="2">
          START
        </text>

        {/* Animated Destination Pin */}
        <g transform={`translate(480, 140) scale(${pinScale}) translate(0, ${pinY})`}>
          <path
            d="M 0 0 C -16 -16 -24 -32 -24 -48 C -24 -64 -12 -76 0 -76 C 12 -76 24 -64 24 -48 C 24 -32 16 -16 0 0 Z"
            fill={accentColor}
            stroke={mapLineColor}
            strokeWidth={strokeWidth}
            strokeLinejoin="round"
          />
          <circle cx="0" cy="-48" r="8" fill={mapSurfaceColor} stroke={mapLineColor} strokeWidth={strokeWidth / 2} />
          <text x="0" y="-95" fontFamily="Inter" fontWeight="800" fontSize="18" fill={mapLineColor} textAnchor="middle" letterSpacing="1">
            GOAL
          </text>
        </g>
      </svg>
    </div>
  );

  const panelBase: React.CSSProperties = {
    width: pW,
    height: pH,
    position: "relative",
    overflow: "hidden",
    transition: "none",
    boxSizing: "border-box",
  };

  const overlayBase: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: "#000000",
    pointerEvents: "none",
    transition: "none",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          perspective: `${s * 1.5}px`,
          transition: "none",
        }}
      >
        {/* Main 3D Wrapper */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            transformStyle: "preserve-3d",
            transform: `translateY(${containerY}px) scale(${containerScale}) rotate(${containerRotate}deg)`,
            filter: `drop-shadow(0px ${dropShadowY}px ${dropShadowBlur}px rgba(0,0,0,0.25))`,
            transition: "none",
          }}
        >
          {/* LEFT PANEL */}
          <div
            style={{
              ...panelBase,
              transformOrigin: "right center",
              transform: `rotateY(${leftRotateY}deg) translateZ(${leftZ}px)`,
              borderTop: `${strokeWidth}px solid ${mapLineColor}`,
              borderBottom: `${strokeWidth}px solid ${mapLineColor}`,
              borderLeft: `${strokeWidth}px solid ${mapLineColor}`,
              borderRight: `${strokeWidth / 2}px solid ${mapLineColor}`,
            }}
          >
            {renderMapContent(0)}
            <div style={{ ...overlayBase, opacity: leftShadow }} />
          </div>

          {/* CENTER PANEL */}
          <div
            style={{
              ...panelBase,
              transformOrigin: "center center",
              borderTop: `${strokeWidth}px solid ${mapLineColor}`,
              borderBottom: `${strokeWidth}px solid ${mapLineColor}`,
              borderLeft: `${strokeWidth / 2}px solid ${mapLineColor}`,
              borderRight: `${strokeWidth / 2}px solid ${mapLineColor}`,
            }}
          >
            {renderMapContent(-pW)}
            <div style={{ ...overlayBase, opacity: centerShadow }} />
          </div>

          {/* RIGHT PANEL */}
          <div
            style={{
              ...panelBase,
              transformOrigin: "left center",
              transform: `rotateY(${rightRotateY}deg) translateZ(${rightZ}px)`,
              borderTop: `${strokeWidth}px solid ${mapLineColor}`,
              borderBottom: `${strokeWidth}px solid ${mapLineColor}`,
              borderRight: `${strokeWidth}px solid ${mapLineColor}`,
              borderLeft: `${strokeWidth / 2}px solid ${mapLineColor}`,
            }}
          >
            {renderMapContent(-pW * 2)}
            <div style={{ ...overlayBase, opacity: rightShadow }} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FoldedMap;